var meters=function(a,b){var R=6371;var p=Math.PI/180;var d1=(b[0]-a[0])*p,d2=(b[1]-a[1])*p;var q=Math.sin(d1/2)**2+Math.cos(a[0]*p)*Math.cos(b[0]*p)*Math.sin(d2/2)**2;return 2*R*Math.atan2(Math.sqrt(q),Math.sqrt(1-q));};
var distance=function(e){if(e.lat===null||e.lat===undefined||e.lng===null||e.lng===undefined)return null;return meters([state.center.lat,state.center.lng],[Number(e.lat),Number(e.lng)]);};
