function header(){modeText();var alias=state.profile&&state.profile.alias||"Mon espace";el("header-user").textContent=state.live&&!state.user?"Connexion":alias;el("header-avatar").textContent=initials(alias);el("location-label").textContent=state.geoAllowed?"Autour de moi · position temporaire":"Louvain-la-Neuve · position par défaut";document.querySelectorAll("[data-action=nav]").forEach(function(b){b.classList.toggle("active",b.dataset.view===state.view);});}
